-- Restores the "starter vocabulary" pack that V9 originally seeded, this time scoped per user
-- instead of global. V11 (multi-tenancy retrofit) truncated all vocabulary including V9's seed,
-- since it had no owner — every account, including brand-new ones, was left with an empty
-- vocabulary list, which defeats the point of a "starter pack" (see decision D18 follow-up).
--
-- Design: a reserved system account ('seed@learnflow.system', never logged into — no UI path
-- creates or authenticates it, and its bcrypt hash is of a random string nobody knows) owns the
-- canonical 300-word template (EN CEFR A1/A2, ZH HSK1/HSK2, JA N5/N4 — same content V9 seeded,
-- copied verbatim). Both this migration's one-time backfill (for every account that existed
-- before this fix) and every future registration (VocabularyService.seedStarterVocabularyFor,
-- called from AuthService.register) clone FROM this template's rows, instead of duplicating the
-- 300-word list a second time in application code.

INSERT INTO app_user (email, password_hash, display_name, created_at)
VALUES (
    'seed@learnflow.system',
    -- bcrypt hash of a random 32-byte string generated at authoring time; nobody has the
    -- plaintext, and there is no registration/login path that would ever target this email.
    '$2a$10$M5mRfnP8Ix4wQFhrAAax7OJMXkgSbpw0/Coe9XYaJgD9VgppTIqJ.',
    'LearnFlow Starter Pack',
    now()
);

INSERT INTO vocabulary_tag (user_id, name)
SELECT (SELECT id FROM app_user WHERE email = 'seed@learnflow.system'), t.name
FROM (VALUES ('A1'), ('A2'), ('HSK1'), ('HSK2'), ('N5'), ('N4')) AS t (name);

-- Same 300-word list V9 originally seeded, now owned by the template account above.
INSERT INTO vocabulary (user_id, language_id, word, meaning, example, attributes, created_at, updated_at)
