INSERT INTO vocabulary_tag_link (vocabulary_id, tag_id)
SELECT v.id, t.id FROM vocabulary v
JOIN vocabulary_tag t
    ON t.user_id = v.user_id
   AND t.name = COALESCE(v.attributes ->> 'cefrLevel', v.attributes ->> 'hskLevel', v.attributes ->> 'jlptLevel')
WHERE v.user_id = (SELECT id FROM app_user WHERE email = 'seed@learnflow.system');

-- Backfill: clone the starter pack into every account that existed before this migration — they
-- lost it when V11 wiped business data with no recorded owner. Safe to run unconditionally (this
-- migration only ever executes once): accounts that already manually added their own words just
-- get the starter pack added alongside them, nothing is overwritten or deduplicated against.
INSERT INTO vocabulary (user_id, language_id, word, meaning, example, attributes, created_at, updated_at)
SELECT u.id, v.language_id, v.word, v.meaning, v.example, v.attributes, now(), now()
FROM app_user u
CROSS JOIN vocabulary v
WHERE v.user_id = (SELECT id FROM app_user WHERE email = 'seed@learnflow.system')
  AND u.email <> 'seed@learnflow.system';

INSERT INTO vocabulary_tag (user_id, name)
SELECT u.id, t.name
FROM app_user u
CROSS JOIN (VALUES ('A1'), ('A2'), ('HSK1'), ('HSK2'), ('N5'), ('N4')) AS t (name)
WHERE u.email <> 'seed@learnflow.system';

INSERT INTO vocabulary_tag_link (vocabulary_id, tag_id)
SELECT v.id, t.id FROM vocabulary v
JOIN vocabulary_tag t
    ON t.user_id = v.user_id
   AND t.name = COALESCE(v.attributes ->> 'cefrLevel', v.attributes ->> 'hskLevel', v.attributes ->> 'jlptLevel')
WHERE t.name IN ('A1', 'A2', 'HSK1', 'HSK2', 'N5', 'N4')
  AND v.user_id <> (SELECT id FROM app_user WHERE email = 'seed@learnflow.system');

-- SRS schedule for every newly cloned word — same "missing schedule" backfill pattern as V10,
-- excluding the template account itself (it is never reviewed).
INSERT INTO review_schedule (vocabulary_id, user_id, next_review)
SELECT v.id, v.user_id, now()
FROM vocabulary v
LEFT JOIN review_schedule rs ON rs.vocabulary_id = v.id
WHERE rs.vocabulary_id IS NULL
  AND v.user_id <> (SELECT id FROM app_user WHERE email = 'seed@learnflow.system');
